#include <bits/stdc++.h>

using namespace std;

int find(vector<int>& parent, int x) {
    if (parent[x] != x) {
        parent[x] = find(parent, parent[x]);
    }
    return parent[x];
}

void unite(vector<int>& parent, int x, int y) {
    int rx = find(parent, x);
    int ry = find(parent, y);
    if (rx != ry) {
        parent[rx] = ry;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);

    int n, m;
    cin >> n >> m;
    vector<vector<char>> a(n, vector<char>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
        }
    }

    vector<vector<int>> ans(n, vector<int>(m));
    vector<int> parent(n * m);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            char tmp = a[i][j];
            a[i][j] = 'W';  // 临时变为水域

            // 初始化并查集
            for (int k = 0; k < n * m; ++k) {
                parent[k] = k;
            }

            // 合并相邻岩石
            for (int x = 0; x < n; ++x) {
                for (int y = 0; y < m; ++y) {
                    if (a[x][y] == 'R') {
                        int idx = x * m + y;
                        if (x > 0 && a[x-1][y] == 'R') {
                            unite(parent, idx, (x-1)*m + y);
                        }
                        if (y > 0 && a[x][y-1] == 'R') {
                            unite(parent, idx, x*m + (y-1));
                        }
                    }
                }
            }

            // 统计连通块数量
            vector<bool> seen(n * m, false);
            int cnt = 0;
            for (int x = 0; x < n; ++x) {
                for (int y = 0; y < m; ++y) {
                    if (a[x][y] == 'R') {
                        int root = find(parent, x * m + y);
                        if (!seen[root]) {
                            seen[root] = true;
                            cnt++;
                        }
                    }
                }
            }
            ans[i][j] = cnt;
            a[i][j] = tmp;  // 恢复
